/**
 * Move uma seleção arbitrária de produtos ativos (por id) para um setor.
 * Nunca toca em produtos com ativo=false (guard .eq('ativo', true)).
 *
 * @param ids      Lista de ids de produtos_master a mover.
 * @param paraSetor Nome do setor de destino.
