async function moverItensSelecionados(
  ids: number[],
  paraSetor: string,
): Promise<SetorResult> {
  if (ids.length === 0) {
    return { ok: false, error: 'Selecione ao menos um item.' };
  }
  if (!paraSetor?.trim()) {
    return { ok: false, error: 'Escolha o setor de destino.' };
  }

  const { data, error } = await supabase
    .from('produtos_master')
    .update({ setor: paraSetor })
    .in('id', ids)
    .eq('ativo', true)
    .select('id');

  if (error) return { ok: false, error: error.message };

  const movidos = data?.length ?? 0;
  await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
  return { ok: true, movidos };
}

