    // chain: .update({setor}) -> .in('id', ids) -> .eq('ativo', true) -> .select('id')
    // A chain precisa terminar no .select('id') que resolve a Promise com { data, error }.
    const eqChain: Record<string, unknown> = {};
    const selectFinalSpy = vi.fn().mockResolvedValue({
